/*
 * mod-moa — script registration.
 * The loader function name is generated by the core from the module folder
 * name: modules/mod-moa -> Addmod_moaScripts().
 */

void AddMOAWorldScript();
void AddMOAProgressionScript();
void AddMOAChallengeScript();
void AddMOACommandScript();
void AddMOARewardScript();

void Addmod_moaScripts()
{
    AddMOAWorldScript();
    AddMOAProgressionScript();
    AddMOAChallengeScript();
    AddMOACommandScript();
    AddMOARewardScript();
}
